			text = [=[Os papéis que McBride sela para {link:goldshire}Vila d'Ouro{/link} contam a história do vale em simples palavras de soldado: kobolds na Serra do Eco, uma irmandade de ladrões que usa bandanas vermelhas e lobos expulsos do leste. Levam também seu julgamento sobre o recruta que os carrega. Os considerados dignos são feitos delegados dos marechais de {link:stormwind-city}Ventobravo{/link}.]=],
		},
	},
	mentions = {
		{ text = "Uma Ameaça Interna" },
