Translate("ptBR", "brother-sammuel", {
	title = "Irmão Sammuel",
	subtitle = "Instrutor de Paladinos",
	found = "O Salão de Armas, dentro da Abadia de Vila Norte",
	hint = "Procure o irmão que treina paladinos no Salão de Armas.",
	allegiance = "Igreja da Luz Sagrada · Abadia de Vila Norte",
	aliases = { "Sammuel" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Irmão Sammuel ensina no Salão de Armas da {link:northshire-abbey}Abadia de Vila Norte{/link}. A ele vêm os chamados a servir a {link:holy-light}Luz Sagrada{/link} com oração e com aço. Ele lhes ensina que a Luz é um fardo antes de ser uma arma.]=],
