Translate("ptBR", "marshal-dughan", {
	title = "Marechal Dughan",
	subtitle = "Marechal de Vila d'Ouro",
	found = "Vila d'Ouro, diante da Estalagem Orgulho do Leão",
	hint = "Fale com o marechal que vigia Vila d'Ouro.",
	allegiance = "Reino de Ventobravo · Exército de Ventobravo",
	aliases = { "Dughan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Da vila-encruzilhada de {link:goldshire}Vila d'Ouro{/link}, o Marechal Dughan comanda a defesa da {link:elwynn-forest}Floresta de Elwynn{/link}. Seus soldados são poucos demais para a tarefa. Ainda assim, ele precisa manter abertas as estradas que ligam a capital às suas fazendas, moinhos e minas. Cada recruta que deixa a {link:northshire-abbey}Abadia de Vila Norte{/link} passa por suas mãos, e ele manda cada um para onde a floresta mais sangra.]=],
		},
		{
			title = "Importância",
			text = [=[Dughan é o rosto de um reino esticado até o limite. {link:stormwind-city}Ventobravo{/link} não tem rei no trono, nem exército por perto, e só conta com a lealdade de homens e mulheres comuns para manter sua paz. Ele não se queixa disso. Simplesmente faz o trabalho que resta.]=],
		},
		{
			title = "Feitos",
			text = [=[• Defende {link:elwynn-forest}Elwynn{/link} com um punhado de soldados, espalhados entre {link:goldshire}Vila d'Ouro{/link}, a {link:westbrook-garrison}Guarnição da Ribeira d'Oeste{/link} e o {link:eastvale-logging-camp}Vale do Leste{/link}.
• Manda batedores à {link:fargodeep-mine}Mina Vailafundo{/link} e à {link:jasperlode-mine}Mina de Jaspe{/link}, onde os kobolds ficam mais ousados a cada dia.
• Oferece recompensa pelo {link:gnolls}gnoll{/link} {link:hogger}Hogger{/link} e pelos saqueadores {link:riverpaw-gnolls}Pata Molhada{/link} da fronteira sul.
• Manda a ajuda que pode aos postos afastados da floresta, embora raramente tenha alguma de sobra.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Pouco se escreveu sobre a vida de Dughan antes de {link:goldshire}Vila d'Ouro{/link}. Esta entrada registra apenas o que seus feitos e seu posto revelam.]=],
		},
	},
	chapters = {
		{
			title = "Os Recrutas de Vila Norte",
			hint = [=[Complete seu treinamento em Vila Norte e apresente-se em Vila d'Ouro.]=],
			text = [=[Os recrutas chegam trazendo cartas do {link:marshal-mcbride}Marechal McBride{/link}. Dughan tem pouco tempo para recebê-los, pois kobolds ocupam as minas, gnolls rondam a fronteira e ladrões assombram todas as estradas. Ele põe cada recém-chegado para trabalhar em menos de uma hora.]=],
		},
		{
			title = "Sob as Colinas",
			hint = "Investigue as minas de Elwynn a mando do Marechal.",
			text = [=[Os relatórios de {link:fargodeep-mine}Vailafundo{/link} e da {link:jasperlode-mine}Mina de Jaspe{/link} confirmam o que Dughan temia. Os kobolds já não são um incômodo a ser expulso com tochas. Estão se espalhando, e cavam mais fundo do que qualquer mineiro honesto jamais ousou.]=],
		},
		{
			title = "A Fronteira do Sul",
			hint = "Resolva a questão de Hogger.",
			text = [=[Por muito tempo, as histórias de {link:hogger}Hogger{/link} foram contadas como causos de beira de fogueira. Dughan parou de tratá-las como histórias quando os mortos começaram a voltar das fazendas do sul.]=],
		},
		{
			title = "O Coletor",
			hint = "Siga o ouro roubado das minas até o fim.",
			text = [=[O pó de ouro roubado das minas não fica com os kobolds. Viaja por estradas ocultas até um agente {link:defias-brotherhood}Défias{/link} conhecido apenas como o Coletor. Quando o anel do Coletor é encontrado, ele traz a marca da velha {link:stonemasons-guild}Guilda dos Pedreiros{/link} de {link:stormwind-city}Ventobravo{/link}. Dughan entende então que os ladrões de {link:elwynn-forest}Elwynn{/link} não são bandidos comuns. São os pedreiros que Ventobravo traiu.]=],
		},
	},
	mentions = {
		{
			text = [=[Apresente-se em {link:goldshire}Vila d'Ouro{/link}, trazido do {link:marshal-mcbride}Marechal McBride{/link}]=],
		},
		{ text = "A {link:fargodeep-mine}Mina Vailafundo{/link}" },
		{ text = "A {link:jasperlode-mine}Mina de Jaspe{/link}" },
		{
			text = [=[A {link:westbrook-garrison}Guarnição da Ribeira d'Oeste{/link} Precisa de Ajuda!]=],
		},
		{
			text = [=[Procura-se: {link:hogger}Hogger{/link}, uma recompensa paga por suas mãos]=],
		},
		{
			text = [=[Um Perigo Escamoso, trazido por {link:remy-two-times}Remy "Duas Vezes"{/link}]=],
		},
		{ text = "Caçada Humana" },
		{ text = "Psiu! Estamos Caçando {link:kobolds}Kobolds{/link}" },
		{ text = "Devolução de Livro" },
		{ text = "Livros Raros" },
	},
	bonds = {
		{ id = "marshal-mcbride", name = "Marechal McBride", note = "manda-lhe recrutas" },
		{ id = "deputy-rainer", name = "Delegado Rainer", note = "defende a Guarnição da Ribeira d'Oeste" },
		{ id = "guard-thomas", name = "Guarda Thomas", note = "vigia o Vale do Leste" },
		{ id = "remy-two-times", name = "Remy \"Duas Vezes\"", note = "traz-lhe notícias" },
		{ id = "hogger", name = "Hogger", note = "inimigo" },
	},
})

