Translate("ptBR", "camping", {
	title = "Acampamento",
	sections = {
		{
			title = "Resumo",
			text = [=[Acampar é a velha arte da estrada: fazer uma fogueira na natureza, dividi-la e descansar ao lado dela antes que a jornada continue. Viajantes por toda {link:azeroth}Azeroth{/link} sempre souberam que uma noite junto a uma boa fogueira pode ser a diferença entre chegar à próxima cidade e nunca chegar.]=],
		},
		{
			title = "O Fogo e os Ofícios",
			text = [=[Um acampamento começa com uma fogueira, feita por quem conhece a arte da culinária. Outros viajantes podem então acrescentar algo a ela, cada um segundo o ofício que conhece. Um ferreiro monta uma roda de afiar. Um coureiro ergue uma tenda. Um alquimista, um encantador, um mineiro ou um alfaiate trazem, cada um, algo seu: um poço de mana, um alaúde encantado, uma pedra-ímã, um estandarte de seu povo. As maiores dessas obras são feitas a partir de planos guardados pelos mestres de cada ofício, e diz-se que alguns desses planos estão nas mãos de inimigos perigosos.]=],
		},
		{
			title = "O Costume do Fogo",
			text = [=[Por costume, cada viajante acrescenta uma única obra a uma fogueira compartilhada, e nenhum ofício é montado duas vezes junto às mesmas chamas. Os que se sentam um tempo junto a tal fogueira levantam-se revigorados, e levam seu benefício consigo por horas na estrada.]=],
		},
	},
})
